from fractions import Fraction as Q
from contextlib import contextmanager
from threading import RLock
from time import monotonic_ns
import json
import sqlite3


def exact(value):
    if isinstance(value, bool) or not isinstance(value, (str, int, Q)):
        raise ValueError('EXACT_REQUIRED')
    if isinstance(value, str) and len(value) > 160:
        raise ValueError('NUMBER_TOO_LONG')
    return Q(value)


def dump(x):
    return json.dumps(x, sort_keys=True, separators=(',', ':'), default=str)


class ManualClock:
    """Trusted test fixture, deliberately not available through Client."""
    source = 'harness_manual_clock'
    def __init__(self, value=0):
        self.value = exact(value)
    def now(self):
        return self.value
    def advance(self, amount):
        amount = exact(amount)
        if amount < 0:
            raise ValueError('NEGATIVE_ADVANCE')
        self.value += amount


class MonotonicClock:
    source = 'python_monotonic_ns'
    def now(self):
        return Q(monotonic_ns(), 10**9)


class Gate:
    """One authority; all accepted transitions and effects are SQL transactions.

    fault is a TEST-ONLY mutant selector, never a client command. Persistent
    storage needs trusted origin/permissions; a fresh fork of the DB is not
    detected by this local design. Unknown completion times are not launchable.
    """
    def __init__(self, clock, beta='1/10', model='model-v1', boot='boot-1',
                 path=':memory:', fault='none', guard=0):
        self.clock, self.lock, self.fault = clock, RLock(), fault
        beta, guard = exact(beta), exact(guard)
        if not 0 <= beta < 1 or guard < 0 or not model or not boot:
            raise ValueError('CONFIG')
        self.db = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
        self.db.executescript('''
        CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY,v TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS leases(id TEXT PRIMARY KEY,body TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,body TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT,body TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS effects(seq INTEGER PRIMARY KEY AUTOINCREMENT,ticket INTEGER, value INTEGER, observed_time TEXT);
        ''')
        config = {'beta':str(beta),'initial_model':model,'boot':boot,'clock_source':clock.source,'guard':str(guard)}
        with self.lock:
            self.db.execute('BEGIN IMMEDIATE')
            try:
                old = self.get('config')
                if old is None:
                    now = exact(clock.now())
                    self.set('config', config); self.set('q', '1')
                    self.set('model', model); self.set('epoch', 0)
                    self.set('stopped', False); self.set('broken_clock', False)
                    self.set('reference', str(now)); self.set('last_time', str(now))
                    self.event('INIT', now, config=config)
                else:
                    if old != config:
                        raise ValueError('REOPEN_CONFIG_OR_CLOCK_DOMAIN')
                    now = self.read_clock()
                    if now is None: raise ValueError('CLOCK_INVALID_ON_REOPEN')
                    # A restart consumes no new budget and does not refund old work.
                    for tid, raw in self.db.execute('SELECT id,body FROM tickets').fetchall():
                        t=json.loads(raw)
                        if t['status']=='PENDING':
                            t['status']='ABORTED'; self.ticket_write(tid,t)
                    self.event('RECOVER',now)
                self.db.execute('COMMIT')
            except BaseException:
                self.db.execute('ROLLBACK'); self.db.close(); raise

    def get(self, key):
        row=self.db.execute('SELECT v FROM meta WHERE k=?',(key,)).fetchone()
        return None if row is None else json.loads(row[0])
    def set(self,key,value):
        self.db.execute('INSERT OR REPLACE INTO meta VALUES (?,?)',(key,dump(value)))
    def event(self,kind,now,**data):
        self.db.execute('INSERT INTO events(body) VALUES (?)',(dump(dict(kind=kind,time=str(now),**data)),))
    def read_clock(self):
        now=exact(self.clock.now()); old=exact(self.get('last_time'))
        if now < old or self.get('broken_clock'):
            self.set('broken_clock',True)
            return None
        self.set('last_time',str(now)); return now
    @contextmanager
    def transaction(self):
        with self.lock:
            self.db.execute('BEGIN IMMEDIATE')
            try:
                now=self.read_clock()
                yield now
                self.db.execute('COMMIT')
            except BaseException:
                self.db.execute('ROLLBACK'); raise
    def deny(self,now,reason):
        # Clock faults are recorded with the previous monotone timestamp.
        self.event('DENY',self.get('last_time') if now is None else now,reason=reason)
        return {'status':'REFUSED','reason':reason}
    def ticket_write(self,tid,t):
        self.db.execute('UPDATE tickets SET body=? WHERE id=?',(dump(t),tid))
    def within(self,t,lease):
        end=exact(self.get('reference'))+exact(lease['until'])
        return t<=end if lease['closed'] or self.fault=='closed_expiry' else t<end

